package com.avsargo.mobile;
import android.app.Activity;
import android.os.Bundle;
import android.graphics.*;
import android.graphics.pdf.PdfRenderer;
import android.os.ParcelFileDescriptor;
import android.widget.*;
import org.json.*;
import java.io.*;
/** Review the original privately. One PDF page is rendered at a time. */
public final class DocumentPreviewActivity extends Activity {
 private ImageView image;private TextView title;private Button previous,next;private byte[] data;private String mime;private int page=0,count=1;private Bitmap shown;private boolean busy=false;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(16,16,16,16);box.setBackgroundColor(Color.rgb(23,24,26));LinearLayout head=new LinearLayout(this);Button close=new Button(this);close.setText("Back");close.setOnClickListener(v->finish());title=new TextView(this);title.setTextColor(Color.WHITE);head.addView(close);head.addView(title);box.addView(head);image=new ImageView(this);image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);box.addView(image,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);previous=new Button(this);previous.setText("Previous page");next=new Button(this);next.setText("Next page");nav.addView(previous);nav.addView(next);box.addView(nav);setContentView(box);previous.setOnClickListener(v->{if(!busy&&page>0){page--;render();}});next.setOnClickListener(v->{if(!busy&&page<count-1){page++;render();}});try{SecureVault vault=new SecureVault(this);String id=getIntent().getStringExtra("documentId");data=vault.documentData(id);mime=vault.documentMeta(id).getString("mime");render();}catch(Exception e){title.setText("Document unavailable");}}
 private void render(){busy=true;previous.setEnabled(false);next.setEnabled(false);new Thread(()->{File temp=null;try{Bitmap bitmap;if("application/pdf".equals(mime)){temp=File.createTempFile("ocr_preview_",".pdf",getCacheDir());try(FileOutputStream out=new FileOutputStream(temp)){out.write(data);}try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(temp,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer pdf=new PdfRenderer(fd)){count=pdf.getPageCount();try(PdfRenderer.Page p=pdf.openPage(page)){float scale=Math.min(2f,1300f/p.getWidth());bitmap=Bitmap.createBitmap(Math.max(1,Math.round(p.getWidth()*scale)),Math.max(1,Math.round(p.getHeight()*scale)),Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.WHITE);p.render(bitmap,null,null,1);}}}else{BitmapFactory.Options opt=new BitmapFactory.Options();opt.inSampleSize=2;bitmap=BitmapFactory.decodeByteArray(data,0,data.length,opt);if(bitmap==null)throw new IOException();}runOnUiThread(()->{if(isFinishing()){bitmap.recycle();return;}Bitmap old=shown;shown=bitmap;image.setImageBitmap(bitmap);if(old!=null)old.recycle();title.setText("Page "+(page+1)+" / "+count);busy=false;previous.setEnabled(page>0);next.setEnabled(page<count-1);});}catch(Exception e){runOnUiThread(()->{busy=false;title.setText("Preview unavailable");});}finally{if(temp!=null)temp.delete();}},"private-preview").start();}
 @Override protected void onDestroy(){image.setImageDrawable(null);if(shown!=null)shown.recycle();data=null;super.onDestroy();}
}
